function buildTopics(): DebateTopicItem[] {
  const list: DebateTopicItem[] = [];
  POLITICAL_AREAS.forEach((category, areaIdx) => {
    const rawList = TOPIC_CATALOG[areaIdx] || [];
    rawList.forEach((item, idx) => {
      const [
        title,
        description,
        difficulty,
        pro1,
        pro2,
        con1,
        con2,
        q1,
        q2,
        popular,
        currentAffairs,
      ] = item;
      list.push({
        id: `t_${areaIdx}_${String(idx + 1).padStart(2, '0')}`,
        title,
        description,
        category,
        difficulty,
        pros: [pro1, pro2],
        cons: [con1, con2],
        followUpQuestions: [q1, q2],
        popular: Boolean(popular),
        currentAffairs: Boolean(currentAffairs),
      });
    });
  });
  return list;
}

export const DEBATE_TOPICS_300: DebateTopicItem[] = buildTopics();
